/**
 * Token Class
 * Represents a single token generated by the Lexical Analyzer
 */

export class Token {
  constructor(tokenNo, lexeme, type, line, column) {
    this.tokenNo = tokenNo;
    this.lexeme = lexeme;
    this.type = type;
    this.line = line;
    this.column = column;
  }

  toJSON() {
    return {
      tokenNo: this.tokenNo,
      lexeme: this.lexeme,
      type: this.type,
      line: this.line,
      column: this.column
    };
  }
}
